import{_ as t,o as e,c as s,a5 as d}from"./chunks/framework.a5no_H3L.js";const x=JSON.parse('{"title":"数据访问诊断总览","description":"数据访问故障常被归到「数据库慢」，但 Java 侧的问题多发生在连接池和事务边界上。连接池耗尽既可能来自数据库慢查询，也可能来自事务持有过长、线程池拥塞或连接未归还。本目录把数据访问的排障入口单列，强调跨层证据链。","frontmatter":{},"headers":[],"relativePath":"java/06-diagnostics/04-data-access/index.md","filePath":"java/06-diagnostics/04-data-access/index.md"}'),i={name:"java/06-diagnostics/04-data-access/index.md"};function c(l,a,n,r,o,f){return e(),s("div",null,[...a[0]||(a[0]=[d('<h1 id="数据访问诊断总览" tabindex="-1" data-src-line="1" data-src-file="java/06-diagnostics/04-data-access/index.md">数据访问诊断总览 <a class="header-anchor" href="#数据访问诊断总览" aria-label="Permalink to &quot;数据访问诊断总览&quot;">​</a></h1><p data-src-line="3" data-src-file="java/06-diagnostics/04-data-access/index.md">数据访问故障常被归到「数据库慢」，但 Java 侧的问题多发生在连接池和事务边界上。连接池耗尽既可能来自数据库慢查询，也可能来自事务持有过长、线程池拥塞或连接未归还。本目录把数据访问的排障入口单列，强调跨层证据链。</p><h2 id="两条主线" tabindex="-1" data-src-line="5" data-src-file="java/06-diagnostics/04-data-access/index.md">两条主线 <a class="header-anchor" href="#两条主线" aria-label="Permalink to &quot;两条主线&quot;">​</a></h2><ul data-src-line="7" data-src-file="java/06-diagnostics/04-data-access/index.md"><li data-src-line="7" data-src-file="java/06-diagnostics/04-data-access/index.md"><a href="./chapter-01-cases-connection-pool-exhaustion.html">连接池耗尽案例</a>：获取连接超时、连接泄漏、慢 SQL 引发的资源占用。重点区分「连接需求超过供给」和「连接被持有不放」。</li><li data-src-line="8" data-src-file="java/06-diagnostics/04-data-access/index.md"><a href="./chapter-02-cases-slow-sql.html">慢 SQL 案例</a>：执行计划变化、锁等待、数据库耗时与应用耗时不一致。重点判断慢在数据库还是应用侧。</li></ul><h2 id="连接池耗尽的跨层归因" tabindex="-1" data-src-line="10" data-src-file="java/06-diagnostics/04-data-access/index.md">连接池耗尽的跨层归因 <a class="header-anchor" href="#连接池耗尽的跨层归因" aria-label="Permalink to &quot;连接池耗尽的跨层归因&quot;">​</a></h2><p data-src-line="12" data-src-file="java/06-diagnostics/04-data-access/index.md">连接池是一个把「应用并发」和「数据库承载能力」隔开的缓冲层。它耗尽时，根因很少只在池本身。</p><table tabindex="0"><thead data-src-line="14" data-src-file="java/06-diagnostics/04-data-access/index.md"><tr data-src-line="14" data-src-file="java/06-diagnostics/04-data-access/index.md"><th style="text-align:left;">你观察到的信号</th><th style="text-align:left;">更可能的根因层</th><th style="text-align:left;">下一步入口</th></tr></thead><tbody data-src-line="16" data-src-file="java/06-diagnostics/04-data-access/index.md"><tr data-src-line="16" data-src-file="java/06-diagnostics/04-data-access/index.md"><td style="text-align:left;">活跃连接数打满、等待线程堆积</td><td style="text-align:left;">数据库慢查询占住连接</td><td style="text-align:left;"><a href="./chapter-02-cases-slow-sql.html">慢 SQL 案例</a></td></tr><tr data-src-line="17" data-src-file="java/06-diagnostics/04-data-access/index.md"><td style="text-align:left;">活跃连接数打满、事务持有时间长</td><td style="text-align:left;">事务边界过大或连接未归还</td><td style="text-align:left;"><a href="./../02-concurrency/chapter-05-cases-async-timeout.html">并发诊断：异步超时</a></td></tr><tr data-src-line="18" data-src-file="java/06-diagnostics/04-data-access/index.md"><td style="text-align:left;">活跃连接数打满、上游线程池也满</td><td style="text-align:left;">上游拥塞传导到数据访问</td><td style="text-align:left;"><a href="./../02-concurrency/chapter-01-concurrency-diagnostics.html">并发诊断总论</a></td></tr><tr data-src-line="19" data-src-file="java/06-diagnostics/04-data-access/index.md"><td style="text-align:left;">连接泄漏缓慢增长、fd 上升</td><td style="text-align:left;">异常路径未关闭连接</td><td style="text-align:left;"><a href="./../03-network/chapter-04-cases-connection-leaks.html">网络案例：连接泄漏</a></td></tr></tbody></table><p data-src-line="21" data-src-file="java/06-diagnostics/04-data-access/index.md">不要把连接池耗尽直接当成「数据库不行」。先确认连接是被慢查询占住、被事务持有，还是根本没归还池，再决定去数据库还是回应用层。</p><h2 id="慢-sql-的归属判断" tabindex="-1" data-src-line="23" data-src-file="java/06-diagnostics/04-data-access/index.md">慢 SQL 的归属判断 <a class="header-anchor" href="#慢-sql-的归属判断" aria-label="Permalink to &quot;慢 SQL 的归属判断&quot;">​</a></h2><p data-src-line="25" data-src-file="java/06-diagnostics/04-data-access/index.md">应用日志报的 SQL 耗时和数据库自身看到的执行耗时未必一致。差异往往来自网络往返、驱动批处理、连接等待或事务包裹。判断归属时先看「等待获取连接的时间」和「真正执行的时间」是否混在一起。</p><ul data-src-line="27" data-src-file="java/06-diagnostics/04-data-access/index.md"><li data-src-line="27" data-src-file="java/06-diagnostics/04-data-access/index.md">若耗时主要在获取连接阶段，问题在连接池，回到 <a href="./chapter-01-cases-connection-pool-exhaustion.html">连接池耗尽案例</a>。</li><li data-src-line="28" data-src-file="java/06-diagnostics/04-data-access/index.md">若获取连接很快但执行慢，再看执行计划和锁等待，进入 <a href="./chapter-02-cases-slow-sql.html">慢 SQL 案例</a>。</li></ul><h2 id="使用方式" tabindex="-1" data-src-line="30" data-src-file="java/06-diagnostics/04-data-access/index.md">使用方式 <a class="header-anchor" href="#使用方式" aria-label="Permalink to &quot;使用方式&quot;">​</a></h2><ol data-src-line="32" data-src-file="java/06-diagnostics/04-data-access/index.md"><li data-src-line="32" data-src-file="java/06-diagnostics/04-data-access/index.md">记录现象、时间点和影响范围，先不猜根因。</li><li data-src-line="33" data-src-file="java/06-diagnostics/04-data-access/index.md">用连接池指标（活跃数、等待数、等待时间）定位是「供给」还是「持有」问题。</li><li data-src-line="34" data-src-file="java/06-diagnostics/04-data-access/index.md">拿到 SQL 执行计划与锁信息后，再判断慢在数据库还是应用。</li><li data-src-line="35" data-src-file="java/06-diagnostics/04-data-access/index.md">修复后同时验证连接池指标恢复、SQL 耗时下降和业务结果正常。</li></ol>',13)])])}const m=t(i,[["render",c]]);export{x as __pageData,m as default};
